BEGIN;
ALTER TABLE public.forge_vtt_assets ADD COLUMN folder text NOT NULL DEFAULT '' CHECK(length(folder)<=120);
CREATE TABLE public.forge_vtt_resources(campaign_id uuid NOT NULL REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,id uuid NOT NULL DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('handout','journal','pin','audio')),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120),audience text NOT NULL DEFAULT 'dm' CHECK(audience IN ('dm','all','selected')),recipients uuid[] NOT NULL DEFAULT '{}',payload jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object' AND octet_length(payload::text)<=65536),revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(campaign_id,id));
CREATE TABLE forge_vtt_private.resource_assets(campaign_id uuid NOT NULL,resource_id uuid NOT NULL,asset_id uuid NOT NULL,PRIMARY KEY(campaign_id,resource_id,asset_id),FOREIGN KEY(campaign_id,resource_id) REFERENCES public.forge_vtt_resources(campaign_id,id) ON DELETE CASCADE,FOREIGN KEY(campaign_id,asset_id) REFERENCES public.forge_vtt_assets(campaign_id,id));
ALTER TABLE forge_vtt_private.resource_assets ENABLE ROW LEVEL SECURITY;REVOKE ALL ON forge_vtt_private.resource_assets FROM PUBLIC,anon,authenticated;
CREATE TABLE public.forge_vtt_preferences(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,data jsonb NOT NULL DEFAULT '{}' CHECK(octet_length(data::text)<=2048));
ALTER TABLE public.forge_vtt_preferences ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.forge_vtt_preferences FROM anon,authenticated;GRANT SELECT ON public.forge_vtt_preferences TO authenticated;
CREATE POLICY vtt_preferences_self ON public.forge_vtt_preferences TO authenticated USING(user_id=(select auth.uid()) AND forge_vtt_private.regular_user(auth.uid()));
CREATE FUNCTION forge_vtt_private.resource_readable(c uuid,rid uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE r public.forge_vtt_resources;BEGIN
 IF NOT forge_vtt_private.member_of(c) THEN RETURN false;END IF;SELECT * INTO r FROM public.forge_vtt_resources WHERE campaign_id=c AND id=rid AND deleted_at IS NULL;IF NOT FOUND THEN RETURN false;END IF;IF forge_vtt_private.dm_of(c) THEN RETURN true;END IF;
 IF NOT(r.audience='all' OR r.audience='selected' AND auth.uid()=ANY(r.recipients)) THEN RETURN false;END IF;
 IF r.kind='pin' THEN IF NOT forge_vtt_private.scene_readable(c,(r.payload->>'sceneId')::uuid) THEN RETURN false;END IF;IF r.payload->>'documentId' IS NOT NULL THEN RETURN forge_vtt_private.resource_readable(c,(r.payload->>'documentId')::uuid);END IF;END IF;RETURN true;END$$;
REVOKE ALL ON FUNCTION forge_vtt_private.resource_readable(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION forge_vtt_private.resource_readable(uuid,uuid) TO authenticated;
ALTER TABLE public.forge_vtt_resources ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.forge_vtt_resources FROM anon,authenticated;GRANT SELECT ON public.forge_vtt_resources TO authenticated;
CREATE POLICY vtt_resources_read ON public.forge_vtt_resources TO authenticated USING(forge_vtt_private.resource_readable(campaign_id,id));
CREATE OR REPLACE FUNCTION forge_vtt_private.asset_readable(c uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT forge_vtt_private.member_of(c) AND EXISTS(SELECT 1 FROM public.forge_vtt_assets x WHERE x.campaign_id=c AND x.id=a AND x.deleted_at IS NULL AND (forge_vtt_private.dm_of(c) OR EXISTS(SELECT 1 FROM forge_vtt_private.resource_assets ra WHERE ra.campaign_id=c AND ra.asset_id=a AND forge_vtt_private.resource_readable(c,ra.resource_id)) OR EXISTS(SELECT 1 FROM public.forge_vtt_asset_uses u WHERE u.campaign_id=c AND u.asset_id=a AND u.audience='campaign' AND ((u.scene_id IS NOT NULL AND forge_vtt_private.scene_readable(c,u.scene_id) AND coalesce((SELECT (sc.settings#>>'{layers,map,visible}')::boolean FROM public.forge_vtt_scenes sc WHERE sc.id=u.scene_id),true)) OR (u.entity_id IS NOT NULL AND forge_vtt_private.entity_readable(c,u.entity_id))))));$$;
CREATE FUNCTION forge_vtt_private.resources_snapshot(c uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('serverTime',floor(extract(epoch from clock_timestamp())*1000),'records',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.updated_at DESC) FROM public.forge_vtt_resources r WHERE r.campaign_id=c AND forge_vtt_private.resource_readable(c,r.id)),'[]'::jsonb),'trash',CASE WHEN forge_vtt_private.dm_of(c) THEN coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM public.forge_vtt_resources r WHERE r.campaign_id=c AND r.deleted_at>now()-interval '30 days'),'[]'::jsonb) ELSE '[]'::jsonb END,'assets',CASE WHEN forge_vtt_private.dm_of(c) THEN coalesce((SELECT jsonb_agg(to_jsonb(a)-'object_path'-'sha256') FROM public.forge_vtt_assets a WHERE a.campaign_id=c),'[]'::jsonb) ELSE '[]'::jsonb END,'preferences',coalesce((SELECT data FROM public.forge_vtt_preferences WHERE user_id=auth.uid()),'{}'::jsonb),'campaignBytes',CASE WHEN forge_vtt_private.dm_of(c) THEN (SELECT coalesce(sum(byte_size),0) FROM public.forge_vtt_assets WHERE campaign_id=c) ELSE 0 END,'accountBytes',CASE WHEN forge_vtt_private.dm_of(c) THEN (SELECT coalesce(sum(a.byte_size),0) FROM public.forge_vtt_assets a JOIN public.forge_vtt_campaigns g ON g.id=a.campaign_id WHERE g.owner_id=(SELECT owner_id FROM public.forge_vtt_campaigns WHERE id=c)) ELSE 0 END)$$;
REVOKE ALL ON FUNCTION forge_vtt_private.resources_snapshot(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.forge_vtt_resources_api(p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=(p_payload->>'campaignId')::uuid;rid uuid:=(p_payload->>'id')::uuid;r public.forge_vtt_resources;data jsonb:=coalesce(p_payload->'payload','{}');k text;asset uuid;item jsonb;owner uuid;bytes bigint;reservation uuid;target uuid;path text;refs uuid[]:='{}';BEGIN
 IF NOT forge_vtt_private.regular_user(auth.uid()) OR NOT forge_vtt_private.member_of(c) OR octet_length(p_payload::text)>80000 THEN RAISE EXCEPTION 'Campaign unavailable' USING ERRCODE='42501';END IF;
 IF p_action='list' THEN RETURN forge_vtt_private.resources_snapshot(c);END IF;
 PERFORM forge_vtt_private.play_limit(c);IF p_action<>'preferences' AND forge_vtt_private.user_role(c,auth.uid())='spectator' THEN RAISE EXCEPTION 'Read-only access' USING ERRCODE='42501';END IF;
 IF p_action='preferences' THEN
 IF NOT forge_vtt_private.allow_keys(data,ARRAY['theme','scale','volume','muted','animations','sound','zoom','snap']) OR data->>'theme' IS NOT NULL AND data->>'theme' NOT IN ('dark','light') OR NOT forge_vtt_private.number_ok(data,'scale',.8,1.4) OR NOT forge_vtt_private.number_ok(data,'volume',0,1) OR NOT forge_vtt_private.number_ok(data,'zoom',.2,2) OR octet_length(data::text)>2048 THEN RAISE EXCEPTION 'Invalid preferences';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(data) v WHERE v.key IN ('muted','animations','sound','snap') AND jsonb_typeof(v.value)<>'boolean') THEN RAISE EXCEPTION 'Invalid preference switch';END IF;
 INSERT INTO public.forge_vtt_preferences(user_id,data) VALUES(auth.uid(),data) ON CONFLICT(user_id) DO UPDATE SET data=EXCLUDED.data;
 ELSIF p_action='journal' THEN
 SELECT * INTO r FROM public.forge_vtt_resources WHERE campaign_id=c AND id=rid FOR UPDATE;
 IF NOT FOUND OR r.deleted_at IS NOT NULL OR r.kind<>'journal' OR r.audience<>'all' OR r.payload->>'shared' IS DISTINCT FROM 'true' OR NOT forge_vtt_private.resource_readable(c,rid) OR length(coalesce(p_payload->>'text',''))>20000 OR r.revision IS DISTINCT FROM (p_payload->>'expected')::bigint THEN RAISE EXCEPTION 'Journal changed or editing unavailable' USING ERRCODE='40001';END IF;
 UPDATE public.forge_vtt_resources SET payload=jsonb_set(payload,'{text}',to_jsonb(coalesce(p_payload->>'text',''))),revision=revision+1,updated_at=now() WHERE campaign_id=c AND id=rid;
 ELSE
 IF NOT forge_vtt_private.dm_of(c) THEN RAISE EXCEPTION 'DM controls required' USING ERRCODE='42501';END IF;
 IF p_action='reserve' THEN
 bytes:=(p_payload->>'bytes')::bigint;IF bytes IS NULL OR bytes NOT BETWEEN 1 AND 20971520 OR p_payload->>'mime' NOT IN ('image/png','image/jpeg','image/webp','audio/mpeg','audio/ogg','audio/wav') THEN RAISE EXCEPTION 'Use PNG/JPEG/WebP or MP3/Ogg/WAV up to 20 MB';END IF;
 SELECT owner_id INTO owner FROM public.forge_vtt_campaigns WHERE id=c;PERFORM pg_advisory_xact_lock(hashtextextended('vtt-storage:'||least(owner::text,auth.uid()::text),0));PERFORM pg_advisory_xact_lock(hashtextextended('vtt-storage:'||greatest(owner::text,auth.uid()::text),0));
 IF (SELECT coalesce(sum(byte_size),0) FROM public.forge_vtt_assets WHERE uploaded_by=auth.uid())+(SELECT coalesce(sum(reserved_bytes),0) FROM forge_vtt_private.upload_reservations WHERE user_id=auth.uid() AND state IN ('reserved','uploaded') AND expires_at>now())+bytes>524288000 THEN RAISE EXCEPTION 'Uploader quota: 500 MB';END IF;
 IF (SELECT coalesce(sum(byte_size),0) FROM public.forge_vtt_assets WHERE campaign_id=c)+(SELECT coalesce(sum(reserved_bytes),0) FROM forge_vtt_private.upload_reservations WHERE campaign_id=c AND state IN ('reserved','uploaded') AND expires_at>now())+bytes>262144000 THEN RAISE EXCEPTION 'Campaign quota: 250 MB';END IF;
 IF (SELECT coalesce(sum(a.byte_size),0) FROM public.forge_vtt_assets a JOIN public.forge_vtt_campaigns g ON g.id=a.campaign_id WHERE g.owner_id=owner)+(SELECT coalesce(sum(q.reserved_bytes),0) FROM forge_vtt_private.upload_reservations q JOIN public.forge_vtt_campaigns g ON g.id=q.campaign_id WHERE g.owner_id=owner AND q.state IN ('reserved','uploaded') AND q.expires_at>now())+bytes>524288000 THEN RAISE EXCEPTION 'Account quota: 500 MB';END IF;
 IF (SELECT count(*) FROM forge_vtt_private.upload_reservations WHERE user_id=auth.uid() AND state='reserved' AND expires_at>now())>=20 THEN RAISE EXCEPTION 'Too many pending uploads';END IF;
 reservation:=gen_random_uuid();target:=gen_random_uuid();path:=c::text||'/'||target::text||'/media';INSERT INTO forge_vtt_private.upload_reservations(id,campaign_id,user_id,asset_id,operation_id,reserved_bytes,object_path,expires_at) VALUES(reservation,c,auth.uid(),target,gen_random_uuid(),bytes,path,now()+interval '15 minutes');RETURN jsonb_build_object('reservationId',reservation,'assetId',target,'path',path);
 ELSIF p_action='asset' THEN
 IF length(coalesce(p_payload->>'label',''))>200 OR length(coalesce(p_payload->>'folder',''))>120 OR jsonb_typeof(coalesce(p_payload->'tags','[]'))<>'array' OR jsonb_array_length(coalesce(p_payload->'tags','[]'))>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_payload->'tags','[]')) tag WHERE length(tag)>40) THEN RAISE EXCEPTION 'Invalid asset metadata';END IF;
 UPDATE public.forge_vtt_assets SET label=coalesce(p_payload->>'label',''),folder=coalesce(p_payload->>'folder',''),tags=ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'tags','[]'))) WHERE campaign_id=c AND id=rid;
 ELSIF p_action='asset_trash' THEN UPDATE public.forge_vtt_assets SET deleted_at=CASE WHEN coalesce((p_payload->>'restore')::boolean,false) THEN NULL ELSE now() END WHERE campaign_id=c AND id=rid AND (deleted_at IS NULL OR deleted_at>now()-interval '30 days');
 ELSIF p_action IN ('trash','restore') THEN
 SELECT * INTO r FROM public.forge_vtt_resources WHERE campaign_id=c AND id=rid FOR UPDATE;IF NOT FOUND OR r.revision IS DISTINCT FROM (p_payload->>'expected')::bigint THEN RAISE EXCEPTION 'Resource changed' USING ERRCODE='40001';END IF;
 IF p_action='restore' AND r.deleted_at<now()-interval '30 days' THEN RAISE EXCEPTION 'Restore period expired';END IF;
 UPDATE public.forge_vtt_resources SET deleted_at=CASE WHEN p_action='restore' THEN NULL ELSE now() END,revision=revision+1,updated_at=now() WHERE campaign_id=c AND id=rid;
 ELSIF p_action='save' THEN
 IF rid IS NULL OR p_payload->>'kind' NOT IN ('handout','journal','pin','audio') OR length(coalesce(p_payload->>'title','')) NOT BETWEEN 1 AND 120 OR coalesce(p_payload->>'audience','dm') NOT IN ('dm','all','selected') OR jsonb_typeof(data)<>'object' OR octet_length(data::text)>65536 OR length(coalesce(data->>'text',''))>20000 OR jsonb_typeof(coalesce(p_payload->'recipients','[]'))<>'array' OR jsonb_array_length(coalesce(p_payload->'recipients','[]'))>30 THEN RAISE EXCEPTION 'Invalid resource';END IF;
 PERFORM 1 FROM public.forge_vtt_campaigns WHERE id=c FOR UPDATE;SELECT * INTO r FROM public.forge_vtt_resources WHERE campaign_id=c AND id=rid FOR UPDATE;
 IF coalesce(r.revision,0) IS DISTINCT FROM (p_payload->>'expected')::bigint OR r.kind IS NOT NULL AND r.kind<>p_payload->>'kind' THEN RAISE EXCEPTION 'Resource changed; reopen before saving' USING ERRCODE='40001';END IF;
 IF r.id IS NULL AND (SELECT count(*) FROM public.forge_vtt_resources WHERE campaign_id=c)>=500 THEN RAISE EXCEPTION 'Resource limit: 500';END IF;
 k:=p_payload->>'kind';IF k IS NULL THEN RAISE EXCEPTION 'Resource kind required';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_payload->'recipients','[]')) u WHERE NOT EXISTS(SELECT 1 FROM public.forge_vtt_campaign_members WHERE campaign_id=c AND user_id=u::uuid)) THEN RAISE EXCEPTION 'Recipient is not in this campaign';END IF;
 IF k IN ('handout','journal') THEN IF NOT forge_vtt_private.allow_keys(data,ARRAY['text','imageAssetId','shared','tokenIds']) OR jsonb_typeof(coalesce(data->'tokenIds','[]')) IS DISTINCT FROM 'array' OR jsonb_array_length(coalesce(data->'tokenIds','[]'))>50 THEN RAISE EXCEPTION 'Invalid document';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(data->'tokenIds','[]')) ti WHERE NOT EXISTS(SELECT 1 FROM public.forge_vtt_entities e WHERE e.campaign_id=c AND e.id=ti::uuid AND e.kind='token' AND e.deleted_at IS NULL)) THEN RAISE EXCEPTION 'Token link unavailable';END IF;IF data->>'imageAssetId' IS NOT NULL THEN refs:=array_append(refs,(data->>'imageAssetId')::uuid);END IF;
 ELSIF k='pin' THEN
 IF NOT forge_vtt_private.allow_keys(data,ARRAY['x','y','sceneId','documentId']) OR NOT data ?& ARRAY['x','y','sceneId'] OR NOT forge_vtt_private.number_ok(data,'x',0,128000) OR NOT forge_vtt_private.number_ok(data,'y',0,128000) OR NOT EXISTS(SELECT 1 FROM public.forge_vtt_scenes WHERE campaign_id=c AND id=(data->>'sceneId')::uuid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Invalid map pin';END IF;
 IF data->>'documentId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.forge_vtt_resources WHERE campaign_id=c AND id=(data->>'documentId')::uuid AND kind IN ('handout','journal') AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Invalid pin document';END IF;
 ELSIF k='audio' THEN
 IF NOT data ?& ARRAY['tracks','status','position','volume','crossfade'] OR NOT forge_vtt_private.allow_keys(data,ARRAY['tracks','currentId','status','position','startedAt','loop','volume','crossfade','sfx']) OR jsonb_typeof(data->'tracks') IS DISTINCT FROM 'array' OR jsonb_array_length(data->'tracks')>50 OR coalesce(data->>'status','') NOT IN ('playing','paused','stopped') OR NOT forge_vtt_private.number_ok(data,'position',0,604800) OR NOT forge_vtt_private.number_ok(data,'volume',0,1) OR NOT forge_vtt_private.number_ok(data,'crossfade',0,10) THEN RAISE EXCEPTION 'Invalid playlist';END IF;
 IF (SELECT count(DISTINCT v->>'id') FROM jsonb_array_elements(data->'tracks') v)<>jsonb_array_length(data->'tracks') OR data->>'currentId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(data->'tracks') v WHERE v->>'id'=data->>'currentId') THEN RAISE EXCEPTION 'Invalid current track or duplicate tracks';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(data->'tracks') LOOP PERFORM (item->>'id')::uuid;IF NOT forge_vtt_private.allow_keys(item,ARRAY['id','title','url','assetId']) OR length(coalesce(item->>'title','')) NOT BETWEEN 1 AND 120 OR item->>'id' IS NULL OR item->>'url' IS NULL AND item->>'assetId' IS NULL OR item->>'url' IS NOT NULL AND (item->>'url'!~'^https://' OR length(item->>'url')>2000) THEN RAISE EXCEPTION 'Use HTTPS audio or a library file';END IF;IF item->>'assetId' IS NOT NULL THEN refs:=array_append(refs,(item->>'assetId')::uuid);END IF;END LOOP;
 IF data ? 'sfx' AND data->'sfx'<>'null'::jsonb THEN IF NOT forge_vtt_private.allow_keys(data->'sfx',ARRAY['trackId','nonce','at']) OR length(coalesce(data#>>'{sfx,nonce}','')) NOT BETWEEN 1 AND 100 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(data->'tracks') t WHERE t->>'id'=data#>>'{sfx,trackId}') THEN RAISE EXCEPTION 'Invalid sound effect';END IF;data:=jsonb_set(data,'{sfx,at}',to_jsonb(floor(extract(epoch from clock_timestamp())*1000)));END IF;
 data:=data||jsonb_build_object('startedAt',floor(extract(epoch from clock_timestamp())*1000));
 END IF;
 FOREACH asset IN ARRAY refs LOOP IF NOT EXISTS(SELECT 1 FROM public.forge_vtt_assets WHERE id=asset AND campaign_id=c AND deleted_at IS NULL AND (k='audio' AND mime_type LIKE 'audio/%' OR k IN ('handout','journal') AND mime_type LIKE 'image/%')) THEN RAISE EXCEPTION 'Asset unavailable';END IF;END LOOP;
 INSERT INTO public.forge_vtt_resources(campaign_id,id,kind,title,audience,recipients,payload,revision) VALUES(c,rid,k,p_payload->>'title',coalesce(p_payload->>'audience','dm'),ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(coalesce(p_payload->'recipients','[]'))),data,coalesce(r.revision,0)+1) ON CONFLICT(campaign_id,id) DO UPDATE SET title=EXCLUDED.title,audience=EXCLUDED.audience,recipients=EXCLUDED.recipients,payload=EXCLUDED.payload,revision=EXCLUDED.revision,updated_at=now(),deleted_at=NULL;
 DELETE FROM forge_vtt_private.resource_assets WHERE campaign_id=c AND resource_id=rid;FOREACH asset IN ARRAY refs LOOP INSERT INTO forge_vtt_private.resource_assets VALUES(c,rid,asset) ON CONFLICT DO NOTHING;END LOOP;
 ELSE RAISE EXCEPTION 'Unknown resource action';END IF;END IF;
 PERFORM forge_vtt_private.play_notify(c);RETURN forge_vtt_private.resources_snapshot(c);END$$;
REVOKE ALL ON FUNCTION public.forge_vtt_resources_api(text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.forge_vtt_resources_api(text,jsonb) TO authenticated;
CREATE FUNCTION public.forge_vtt_finalize_media(p_user uuid,p_reservation uuid,p_mime text,p_sha text,p_width integer,p_height integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE q forge_vtt_private.upload_reservations;BEGIN
 SELECT * INTO q FROM forge_vtt_private.upload_reservations WHERE id=p_reservation FOR UPDATE;IF NOT FOUND OR q.user_id<>p_user OR q.expires_at<now() OR forge_vtt_private.user_role(q.campaign_id,p_user) IS DISTINCT FROM 'dm' OR NOT forge_vtt_private.regular_user(p_user) THEN RAISE EXCEPTION 'Upload unavailable';END IF;IF q.state='finalized' THEN RETURN q.asset_id;END IF;
 IF p_mime NOT IN ('image/png','image/jpeg','image/webp','audio/mpeg','audio/ogg','audio/wav') OR p_mime LIKE 'image/%' AND (p_width IS NULL OR p_height IS NULL OR p_width NOT BETWEEN 1 AND 8000 OR p_height NOT BETWEEN 1 AND 8000) THEN RAISE EXCEPTION 'Invalid media';END IF;
 INSERT INTO public.forge_vtt_assets(id,campaign_id,uploaded_by,object_path,mime_type,byte_size,width_px,height_px,sha256) VALUES(q.asset_id,q.campaign_id,p_user,q.object_path,p_mime,q.reserved_bytes,p_width,p_height,p_sha);UPDATE forge_vtt_private.upload_reservations SET state='finalized' WHERE id=q.id;RETURN q.asset_id;END$$;
REVOKE ALL ON FUNCTION public.forge_vtt_finalize_media(uuid,uuid,text,text,integer,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.forge_vtt_finalize_media(uuid,uuid,text,text,integer,integer) TO service_role;
UPDATE storage.buckets SET allowed_mime_types=ARRAY['image/png','image/jpeg','image/webp','audio/mpeg','audio/ogg','audio/wav'] WHERE id='vtt-assets';
COMMIT;
